import { cn } from '@/lib/utils'
import { useTheme } from '@/themes'

const assetPath = (path: string) => `${import.meta.env.BASE_URL}${path.replace(/^\/+/, '')}`

// Brand badge: the KROHN mark in the app-icon squircle, theme-aware —
// light mode shows the black glyph on the ivory squircle, dark mode the
// white glyph on the carbon squircle. The mark PNG carries the rounded shape
// and transparent corners, so no tile/rounding classes here. Generated by
// scripts/generate_icons.py from the KROHN glyph SVGs + squircle backgrounds;
// size via className (default size-14).
export function BrandMark({ className, ...props }: React.ComponentProps<'span'>) {
  const { renderedMode } = useTheme()
  const dark = renderedMode === 'dark'

  return (
    <span className={cn('inline-flex size-14 shrink-0 items-center justify-center', className)} {...props}>
      <img alt="" className="size-full object-contain" src={assetPath(dark ? 'krohn-mark-dark.png' : 'krohn-mark.png')} />
    </span>
  )
}
